import java.util.regex.Pattern;

public class SecureApp {
    // Regular expression to validate URL format and restrict internal hosts
    private static final Pattern URL_PATTERN = Pattern.compile(
        "^(https?://)?([a-zA-Z0-9.-]+)(:\\d+)?(/[a-zA-Z0-9._-]*)*$"
    );

    public static void fetchResource(String userInputUrl) throws Exception {
        // Validate the URL format
        if (!URL_PATTERN.matcher(userInputUrl).matches()) {
            throw new IllegalArgumentException("Invalid URL format");
        }

        // Check if the URL points to a local or internal resource
        URL url = new URL(userInputUrl);
        if ("localhost".equals(url.getHost()) || url.getHost().startsWith("127.")) {
            throw new SecurityException("Access to local resources is not allowed");
        }

        // Safe to proceed
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");

        BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
        String inputLine;
        while ((inputLine = in.readLine()) != null) {
            System.out.println(inputLine);
        }
        in.close();
    }

    public static void main(String[] args) throws Exception {
